        authorize_args(node_id, placement, canary_plan, record, expected),
    )
}

fn authorize_args<'a>(
    node_id: &'a str,
    placement: &'a str,
    canary_plan: Option<&'a str>,
    record: &'a str,
    expected: Option<&'a str>,
) -> Vec<&'a str> {
    let mut args = default_args(if canary_plan.is_some() {
        "authorize-canary"
    } else {
        "authorize"
    });
    args.extend(["--node-id", node_id, "--placement-entry", placement]);
    if let Some(canary_plan) = canary_plan {
        args.extend(["--canary-plan", canary_plan]);
    }
    args.extend(["--activation-record", record]);
    append_expected(&mut args, "--expected-head", expected);
    args.extend(["--format", "json"]);
    args
}

fn append_expected<'a>(args: &mut Vec<&'a str>, flag: &'a str, expected: Option<&'a str>) {
    if let Some(expected) = expected {
        args.extend([flag, expected]);
    }
}

fn placement_args(command: &str) -> Vec<&str> {
    vec![
